#!/usr/bin/env python3
"""Signed caloric renewal in a tail generated by the actual NS vector field.

On the normalized 2*pi torus, u_hat(k)=i*a(k). Three planar parent waves
at squared radius eleven start with an empty tail above squared radius
sixteen. We compute the exact degree-ten polynomial for fully high renewal
of their first generated tail, including both internal output cutoffs.

This is finite rational algebra, not a Lean certificate. Local smoothness
turns the coefficient into a small-time sign, but no quantitative time
window, dissipation-excess bound or recurrent absorption estimate is given.
"""
import argparse
from fractions import Fraction as F
import json

from fourier_interactions import (A, B, add, pair, radius_squared, require,
                                  scale, validate)
from caloric_force import (bilinear_heat_blocks, block_pair, capacity,
                           derivative, parent_derivative)


PARENTS = ((3, 1, 1), (1, 3, 1), (1, -1, 3))
CUTOFF_SQUARED = F(16)


def exponent_add(a, b):
    return tuple(x+y for x, y in zip(a, b))


def polynomial_add(*polynomials):
    out = {}
    for polynomial in polynomials:
        for exponent, field in polynomial.items():
            out[exponent] = add(out.get(exponent, {}), field)
    return {e: u for e, u in out.items() if u}


def polynomial_bilinear(left, right, operation):
    """Expand every parent monomial; no coefficient is fitted from samples."""
    out = {}
    for e, u in left.items():
        for f, v in right.items():
            exponent = exponent_add(e, f)
            out[exponent] = add(out.get(exponent, {}), operation(u, v))
    return {e: u for e, u in out.items() if u}


def high(field):
    return {k: a for k, a in field.items() if radius_squared(k) >= CUTOFF_SQUARED}


def polynomial_high(polynomial):
    return {e: v for e, u in polynomial.items() if (v := high(u))}


def monomial(exponent, parameters):
    value = F(1)
    for a, k in zip(parameters, exponent):
        value *= a**k
    return value


def evaluate(polynomial, parameters):
    return add(*(scale(monomial(e, parameters), u) for e, u in polynomial.items()))


def initial_polynomial():
    polynomial = {}
    for i, k in enumerate(PARENTS):
        e = tuple(int(j == i) for j in range(3))
        a = (-F(k[1]), F(k[0]), F(0))
        polynomial[e] = {k: a, tuple(-x for x in k): tuple(-x for x in a)}
    return polynomial


def renewal_polynomial():
    initial = initial_polynomial()
    child = polynomial_high(polynomial_bilinear(initial, initial, B))
    direction = polynomial_high(polynomial_bilinear(child, child, B))
    source = polynomial_bilinear(child, child, bilinear_heat_blocks)
    tangent = polynomial_add(
        polynomial_bilinear(child, direction, bilinear_heat_blocks),
        polynomial_bilinear(direction, child, bilinear_heat_blocks))
    result = {}
    for e, left in source.items():
        for f, right in tangent.items():
            exponent = exponent_add(e, f)
            coefficient = 2*block_pair(left, right, F(1), CUTOFF_SQUARED)
            result[exponent] = result.get(exponent, F(0))+coefficient
    result = {e: c for e, c in result.items() if c}
    expected = {
        (4, 4, 2): F(119165596729344, 18702263125),
        (4, 2, 4): -F(65074050367488, 2764682375),
        (2, 4, 4): F(1137033707802853376, 113454132553125),
    }
    require(result == expected, 'complete degree-ten parent polynomial')
    return initial, child, result


def check_parameters(initial, child, polynomial, parameters, nu):
    u = evaluate(initial, parameters)
    validate(u)
    require(set(map(radius_squared, u)) == {11}, 'one initial frequency shell')
    require(not high(u), 'the entire initial high tail is empty')
    v = evaluate(child, parameters)
    validate(v)
    actual_rhs = add(B(u, u), scale(-nu, A(u)))
    require(v == high(actual_rhs), 'child is the actual unforced tail derivative')
    direction = high(B(v, v))
    renewal = parent_derivative(v, direction, nu, CUTOFF_SQUARED)
    require(renewal == derivative(v, direction, nu, CUTOFF_SQUARED),
            'independent quartic polarization of the child capacity')
    formula = sum((c*monomial(e, parameters) for e, c in polynomial.items()), F(0))/nu**2
    require(renewal == formula, 'parameter polynomial and viscosity scaling')
    return {'parameters': [str(a) for a in parameters], 'viscosity': str(nu),
            'initial_modes': len(u), 'generated_high_modes': len(v),
            'initial_squared_velocity_norm': str(pair(u, u)),
            'child_capacity': str(capacity(v, nu, CUTOFF_SQUARED)),
            'child_enstrophy_production': str(pair(A(v), B(v, v))),
            'fully_high_renewal_coefficient': str(renewal)}


def check_kida():
    from kida_pelz_birth import initial_field
    u = initial_field()
    validate(u)
    require(not high(u), 'Kida tail initially empty')
    v = high(B(u, u))
    validate(v)
    require(len(v) == 96, 'complete first Kida tail')
    direction = high(B(v, v))
    coefficient = parent_derivative(v, direction, F(1), CUTOFF_SQUARED)
    expected = F(272815689845067746234550784951500983,
                 480261442447688338849788624568320000000)
    require(coefficient == expected and coefficient > 0,
            'positive fully high renewal in the generated Kida tail')
    return {'initial_modes': len(u), 'generated_high_modes': len(v),
            'coefficient_over_inverse_viscosity_squared': str(coefficient)}


def fft_check(child, parameters, n, quadrature_order):
    """Independent physical convection, stretching and heat quadrature at nu=1."""
    import numpy as np
    from numpy.polynomial.laguerre import laggauss

    field = evaluate(child, parameters)
    frequencies = np.rint(np.fft.fftfreq(n)*n)
    k = np.array(np.meshgrid(frequencies, frequencies, frequencies, indexing='ij'))
    ksq = np.sum(k*k, axis=0)
    safe_ksq = np.where(ksq == 0, 1., ksq)
    mask = ksq >= float(CUTOFF_SQUARED)

    def packed(u):
        out = np.zeros((3, n, n, n), dtype=complex)
        for mode, a in u.items():
            out[(slice(None),)+tuple(x % n for x in mode)] = 1j*n**3*np.array(a, dtype=float)
        return out

    def fft(u):
        return np.fft.fftn(u, axes=(1, 2, 3))

    def physical(u):
        return np.fft.ifftn(u, axes=(1, 2, 3)).real

    def kcross(u):
        return np.array([k[1]*u[2]-k[2]*u[1], k[2]*u[0]-k[0]*u[2],
                         k[0]*u[1]-k[1]*u[0]])

    v = packed(field)
    velocity = physical(v)
    convection = fft(-sum(velocity[j]*physical(1j*k[j]*v) for j in range(3)))
    full_direction = convection-k*np.sum(k*convection, axis=0)/safe_ksq
    expected_direction = packed(B(field, field))
    source_error = float(np.linalg.norm(full_direction-expected_direction)
                         / np.linalg.norm(expected_direction))
    require(source_error < 1e-11, 'independent complete physical convection')
    direction = np.where(mask, full_direction, 0.)

    def heat_pair(r):
        heat = np.exp(-r*ksq)
        w, h = heat*v, heat*direction
        omega, domega = physical(1j*kcross(w)), physical(1j*kcross(h))
        stretching = np.zeros_like(velocity)
        tangent = np.zeros_like(velocity)
        for j in range(3):
            grad_w, grad_h = physical(1j*k[j]*w), physical(1j*k[j]*h)
            stretching += omega[j]*grad_w
            tangent += domega[j]*grad_w+omega[j]*grad_h
        m = np.where(mask, 1j*kcross(fft(stretching))/safe_ksq, 0.)
        dm = np.where(mask, 1j*kcross(fft(tangent))/safe_ksq, 0.)
        return float(np.vdot(m, dm).real/n**6)

    # Three child factors and the high nonlinear output give this lower heat rate.
    rate = 3*min(map(radius_squared, field))+float(CUTOFF_SQUARED)
    nodes, weights = laggauss(quadrature_order)
    measured = 2*sum(w*np.exp(x)*heat_pair(x/rate)
                     for x, w in zip(nodes, weights))/rate
    expected = float(parent_derivative(field, high(B(field, field)), F(1), CUTOFF_SQUARED))
    relative_error = abs(measured-expected)/abs(expected)
    require(relative_error < 1e-10, 'independent physical-space caloric coefficient')
    return {'n': n, 'quadrature_order': quadrature_order,
            'parameters': [str(a) for a in parameters], 'coefficient': measured,
            'source_relative_error': source_error, 'renewal_relative_error': relative_error}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--kida', action='store_true', help='also check the 96-mode Kida child')
    parser.add_argument('--fft-check', action='store_true',
                        help='check physical-space products and heat quadrature (NumPy)')
    args = parser.parse_args()
    initial, child, polynomial = renewal_polynomial()
    parameters = ((F(1, 2),)*3, (F(1, 2), F(1), F(1, 2)),
                  (F(1), F(2), F(1)))
    rows = [check_parameters(initial, child, polynomial, a, nu)
            for nu in (F(1), F(1, 1000)) for a in parameters]
    require(F(rows[0]['fully_high_renewal_coefficient']) < 0,
            'equal parent weights have negative leading renewal')
    require(F(rows[1]['fully_high_renewal_coefficient']) > 0,
            'doubling one parent produces positive leading renewal')
    report = {'status': 'all rational checks passed',
        'scope': 'actual first-tail coefficient; no quantitative time window or cumulative budget',
        'polynomial_at_nu_one': {str(e): str(c) for e, c in polynomial.items()},
        'rows': rows}
    if args.kida:
        report['kida'] = check_kida()
    if args.fft_check:
        report['independent_fft_checks'] = [fft_check(child, a, n, q)
            for a in parameters[:2] for n, q in ((32, 32), (48, 64))]
    print(json.dumps(report, indent=2))


if __name__ == '__main__':
    main()
